const lastReasonEnd = `-- name: LastReasonEnd :one
SELECT GREATEST(
    (SELECT s.created_at FROM stream s WHERE s.id = $1::uuid),
    COALESCE((SELECT max(x.finished_at) FROM stream_step x WHERE x.stream_id = $1::uuid), 'epoch'::timestamptz),
    COALESCE((SELECT max(j.created_at) FROM stream_journal j WHERE j.stream_id = $1::uuid AND j.event NOT IN ('orphan', 'reconcile_error', 'ask_shown')), 'epoch'::timestamptz)
)::timestamptz AS at
`

// When the stream's last live reason ended: a step finished, a wait or ask
// resolved, a state change. Orphans found long after it are silent stops.
func (q *Queries) LastReasonEnd(ctx context.Context, streamID pgtype.UUID) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, lastReasonEnd, streamID)
	var at pgtype.Timestamptz
	err := row.Scan(&at)
	return at, err
}

