const listActiveStreams = `-- name: ListActiveStreams :many

SELECT id, workspace_id, slug, title, charter, summary, state, reason, until, weight, min_share, max_parallel, manager_agent_id, carrier_project_id, next_seq, fail_streak, last_milestone_at, active, created_at, updated_at FROM stream WHERE active ORDER BY created_at
`

// Fabrika queries (own sqlc file: sqlc.streams.yaml → internal/streams/sdb).
func (q *Queries) ListActiveStreams(ctx context.Context) ([]Stream, error) {
	rows, err := q.db.Query(ctx, listActiveStreams)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Stream{}
	for rows.Next() {
		var i Stream
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Slug,
			&i.Title,
			&i.Charter,
			&i.Summary,
			&i.State,
			&i.Reason,
			&i.Until,
			&i.Weight,
			&i.MinShare,
			&i.MaxParallel,
			&i.ManagerAgentID,
			&i.CarrierProjectID,
			&i.NextSeq,
			&i.FailStreak,
			&i.LastMilestoneAt,
			&i.Active,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

